<template>
 <MediaGallery v-if="store.panel==='logo'||pickingImage" :model-value="true" :type="key==='users'?'avatar':key==='logo'?'logo':'gallery'" @update:model-value="!$event&&(pickingImage?pickingImage=false:store.closePanel())" @select="selectLogo" />
 <SetupDialog :model-value="!!store.panel&&store.panel!=='logo'&&!pickingImage" :title="title" :description="description" :eyebrow="store.snapshot?.data.company.name" :busy="saving" @close="close">
  <div v-if="loading" role="status" class="setup-note">جار تحميل الإعداد…</div><div v-if="error" class="setup-error" role="alert">{{ error }} <button type="button" class="setup-btn setup-btn-quiet" @click="load">إعادة المحاولة</button></div><div v-if="message" class="setup-note" role="status">{{ message }}</div>
  <template v-if="!loading&&allowed">
   <StoreLocationPicker v-if="key==='location'" v-model="form" label="مكان العنوان" />
   <template v-else-if="key==='policies'"><section class="setup-section"><h3>البيع والمرتجعات</h3><p>هذه السياسة من إدارة المنصة، وليست إعدادًا يمكن للبائع تغييره.</p><dl v-if="snapshot.data.store"><dt>عمولة المنتجات</dt><dd>{{ snapshot.data.store.policy?.commission_percent }}% + {{ (snapshot.data.store.policy?.commission_fixed_minor||0)/100 }} جنيه</dd><dt>إرجاع لتغيير الرأي</dt><dd>{{ snapshot.data.store.return_policy?.change_of_mind_days }} يومًا بحسب السياسة واستثناءاتها</dd><dt>إرجاع بسبب عيب</dt><dd>{{ snapshot.data.store.return_policy?.defect_days }} يومًا بحسب السياسة</dd></dl><p class="setup-help">حفظ بيانات المتجر لا ينشر منتجًا ولا يفتح استقبال الطلبات تلقائيًا.</p></section></template>
   <template v-else-if="key==='subscription'"><dl v-if="subscription"><dt>الباقة</dt><dd>{{ subscription.plan?.name||subscription.plan_name||'الباقة الحالية' }}</dd><dt>الحالة</dt><dd>{{ ({active:'نشط',trial:'تجريبي',pending:'بانتظار التفعيل',expired:'منتهٍ',canceled:'ملغي'})[subscription.status]||subscription.status||'غير متاح' }}</dd><dt>تاريخ الانتهاء</dt><dd>{{ subscription.ends_at||'غير محدد' }}</dd></dl><ul v-if="subscription?.limits" class="setup-list"><li v-for="(limit,name) in subscription.limits" :key="name" class="setup-list-row"><span>{{ ({products:'المنتجات',invoices:'الفواتير',users:'المستخدمون',warehouses:'المخازن',branches:'الفروع',storage_size:'مساحة التخزين',whatsapp_messages:'رسائل واتساب',api_calls:'طلبات الربط',projects:'المشاريع'})[name]||name }}</span><span>{{ limit.used??limit.current??0 }} / {{ limit.is_unlimited?'غير محدود':limit.max??limit.limit??'غير محدد' }}</span></li></ul><p v-if="!subscription">لم تتوفر بيانات اشتراك نشط.</p><p class="setup-help">لا يغير فتح هذه النافذة باقتك أو يشتري خدمات.</p></template>
   <template v-else-if="recordMode&&view==='list'"><div class="setup-section" style="display:flex;flex-wrap:wrap;gap:10px"><button v-if="canCreate" type="button" class="setup-btn setup-btn-primary" @click="edit(null)">{{ createLabel }}</button><label class="setup-label setup-grow">بحث في المعروض<input v-model="search" class="setup-input" type="search" /></label></div><ul class="setup-list"><li v-for="record in filtered" :key="record.id" class="setup-list-row"><span>{{ recordLabel(record) }}<small v-if="record.is_global" style="display:block">إعداد عام للمنصة</small></span><span style="display:flex;gap:6px;flex-wrap:wrap"><button v-if="key==='permissions'" type="button" class="setup-btn" @click="edit(record)">الصلاحيات</button><button v-else-if="canEdit&&(!record.is_global||user.hasPermission('admin.super'))" type="button" class="setup-btn" @click="edit(record)">تعديل</button></span></li></ul><p v-if="!filtered.length" class="setup-help">لا توجد نتائج معروضة. أضف سجلًا إذا احتجت إليه.</p><button v-if="page<lastPage" type="button" class="setup-btn" @click="loadMore">عرض المزيد</button></template>
   <template v-else>
    <component :is="['users','roles','permissions'].includes(key)?'div':'form'" id="setup-option-form" @submit.prevent="save"><fieldset :disabled="saving||!canEditCurrent">
     <p v-if="schema?.note" class="setup-note">{{ schema.note }}</p>
     <UserForm v-if="key==='users'" ref="specificForm" v-model="form" :is-edit-mode="!!editingId" hide-actions external-media @request-media="pickingImage=true" @save="saveUser" />
     <RoleForm v-else-if="key==='roles'" ref="specificForm" :key="editingId||'new'" :role="form" :available-permissions="sources.permissions||[]" :is-edit-mode="!!editingId" @save="saveUser" />
     <UserPermissionManager v-else-if="key==='permissions'&&permissionUser" :user="permissionUser" @save="permissionSaved" @cancel="back" />
     <template v-else-if="key==='billing'||key==='cash_customer'"><p class="setup-help">تجهيز الإعدادات لا ينشئ فواتير أو أرصدة افتتاحية.</p><label class="setup-check"><input v-model="form.create_cash_customer" type="checkbox" />تجهيز عميل نقدي للبيع دون اسم عميل، إن لم يوجد</label><template v-if="key==='billing'"><label class="setup-check"><input v-model="form.create_invoice_types" type="checkbox" />تجهيز أنواع البيع والشراء والمرتجعات الناقصة</label><fieldset class="setup-section"><legend>أنواع الفواتير المتاحة</legend><label v-for="type in snapshot.data.invoice_types" :key="type.id" class="setup-check"><input v-model="form.invoice_type_ids" type="checkbox" :value="type.id" />{{ type.name }}</label></fieldset><label class="setup-label">وسيلة استلام الأموال<select v-model="form.payment_method_id" class="setup-input"><option :value="null">إضافة وسيلة جديدة</option><option v-for="method in snapshot.data.payment_methods" :key="method.id" :value="method.id">{{ method.name }}</option></select></label><label v-if="!form.payment_method_id" class="setup-label">اسم الوسيلة الجديدة<input v-model="form.payment_method_name" class="setup-input" required /></label><label v-if="!snapshot.data.cash_boxes.length" class="setup-check"><input v-model="form.create_cash_box" type="checkbox" />تجهيز خزنة افتراضية دون رصيد افتتاحي</label><p v-else class="setup-help">الخزائن المتاحة: {{ snapshot.data.cash_boxes.map(b=>b.name).join('، ') }}</p></template></template>
     <SetupFields v-else v-model="form" :fields="fields" :sources="sources" />
     <div v-if="['brands','categories','payments'].includes(key)" style="margin-top:14px"><button type="button" class="setup-btn" @click="pickingImage=true">اختيار صورة</button><span v-if="form.image_id" class="setup-help">صورة محفوظة مع السجل</span></div>
     <StoreLocationPicker v-if="schema?.map" v-model="form" label="مكان المخزن" />
     <template v-if="schema?.steps"><section class="setup-section" style="margin-top:20px"><h3>خطوات الإرسال</h3><p class="setup-help">الأيام السالبة تعني قبل الموعد، والموجبة بعده. الأحداث الفورية تُرسل دون تأخير.</p><div v-for="(step,i) in form.steps" :key="i" class="setup-section"><h4>الخطوة {{ i+1 }}</h4><SetupFields :model-value="step" :fields="stepFields" :sources="sources" @update:model-value="form.steps[i]=$event" /><button type="button" class="setup-btn setup-btn-quiet" @click="form.steps.splice(i,1)">إزالة الخطوة</button></div><button type="button" class="setup-btn" @click="form.steps.push({step_number:form.steps.length+1,delay_days:0,channel:['email'],template_id:null,is_active:true})">إضافة خطوة إرسال</button></section></template>
    </fieldset></component>
    <details v-if="schema?.test&&editingId" class="setup-details"><summary>اختبار الإرسال — بإجراء منك فقط</summary><div><label class="setup-label">{{ key==='email'?'بريد المستلم':'رقم المستلم مع رمز الدولة' }}<input v-model="testRecipient" class="setup-input" :type="key==='email'?'email':'tel'" /></label><button type="button" class="setup-btn" :disabled="saving||!testRecipient" @click="testConnection">إرسال رسالة اختبار</button></div></details>
   </template>
  </template>
  <template #actions><button type="button" class="setup-btn" :disabled="saving" @click="recordMode&&view==='edit'?back():close()">{{ recordMode&&view==='edit'?'العودة للقائمة':'إغلاق' }}</button><span class="setup-grow" /><template v-if="allowed&&!loading&&editable"><button type="button" class="setup-btn" :disabled="saving" @click="cancel">إلغاء التعديلات</button><button v-if="key!=='permissions'" :type="['users','roles','location'].includes(key)?'button':'submit'" :form="['users','roles','location'].includes(key)?undefined:'setup-option-form'" class="setup-btn setup-btn-primary" :disabled="saving||!canEditCurrent||(key==='location'&&!form.location_confirmed)" @click="['users','roles'].includes(key)?specificForm?.handleSubmit():key==='location'?saveLocation():undefined">{{ saving?'جار الحفظ…':key==='location'?'استخدام المكان المؤكد':'حفظ التغييرات' }}</button></template></template>
 </SetupDialog>
</template>
<script setup>
import {computed,defineAsyncComponent,ref,watch} from 'vue'
import {useUserStore} from '@/stores/user'
import api from '../api/setupApi'
import SetupDialog from './SetupDialog.vue'
import SetupFields from './SetupFields.vue'
import StoreLocationPicker from '@/modules/store/components/StoreLocationPicker.vue'
import {useCompanySetupStore} from '../store/useCompanySetupStore'
import {listData,optionSchemas,optionTitles,optionPermissions} from '../config/setupOptions'
const UserForm=defineAsyncComponent(()=>import('@/modules/users/components/UserForm.vue')),RoleForm=defineAsyncComponent(()=>import('@/modules/users/components/RoleForm.vue')),UserPermissionManager=defineAsyncComponent(()=>import('@/modules/users/components/UserPermissionManager.vue')),MediaGallery=defineAsyncComponent(()=>import('@/components/common/MediaGallery.vue'))
const store=useCompanySetupStore(),user=useUserStore(),key=computed(()=>store.panel),snapshot=computed(()=>store.snapshot),schema=computed(()=>optionSchemas[key.value]),title=computed(()=>optionTitles[key.value]||'إعدادات إضافية')
const loading=ref(false),saving=ref(false),error=ref(''),message=ref(''),allowed=ref(false),form=ref({}),baseline=ref(''),records=ref([]),sources=ref({}),editingId=ref(null),view=ref('list'),search=ref(''),subscription=ref(null),specificForm=ref(),permissionUser=ref(null),testRecipient=ref(''),pickingImage=ref(false),page=ref(1),lastPage=ref(1)
let sequence=0
const clone=v=>JSON.parse(JSON.stringify(v))
const manager=computed(()=>user.hasPermission('admin.super')||user.hasPermission('admin.company')||user.hasPermission('guidance.setup.manage'))
const recordMode=computed(()=>!!schema.value||['users','roles','permissions','invoices'].includes(key.value))
const endpoint=computed(()=>{const resource=schema.value?.endpoint||({users:'users',roles:'roles',permissions:'users',invoices:'invoice-types'})[key.value];return resource?'guidance/setup/resources/'+resource:null})
const permPrefix=computed(()=>schema.value?.permission||({users:'users',roles:'roles',permissions:'users',invoices:'invoice_types'})[key.value])
const createLabel=computed(()=>({groups:'إضافة مجموعة وحدات',units:'إضافة وحدة',conversions:'إضافة تحويل',categories:'إضافة تصنيف',brands:'إضافة علامة تجارية',branches:'إضافة فرع',warehouses:'إضافة مخزن',payments:'إضافة وسيلة دفع',cashboxes:'إضافة خزنة',email:'إضافة حساب بريد',whatsapp:'إضافة حساب واتساب',templates:'إضافة قالب',automation:'إضافة تنبيه',users:'إضافة موظف',roles:'إضافة دور وظيفي'})[key.value]||'إضافة سجل')
const canCreate=computed(()=>key.value!=='permissions'&&key.value!=='invoices'&&(user.hasPermission('admin.super')||user.hasPermission('admin.company')||user.hasPermission(permPrefix.value+'.create')))
const canEdit=computed(()=>user.hasPermission('admin.super')||user.hasPermission('admin.company')||user.hasPermission(permPrefix.value+'.update_all')||user.hasPermission(permPrefix.value+'.update_self'))
const canEditCurrent=computed(()=>recordMode.value?(editingId.value?canEdit.value:canCreate.value):manager.value||key.value==='location')
const editable=computed(()=>!['policies','subscription','logo'].includes(key.value)&&(!recordMode.value||view.value==='edit'))
const description=computed(()=>key.value==='location'?'اختر النقطة وراجعها ثم أكدها.':recordMode.value&&view.value==='list'?'راجع الموجود أو أضف ما تحتاجه. لن نحذف إعدادًا قائمًا.':'تعديلات هذه النافذة مستقلة عن مسودة دليل الإعداد.')
const filtered=computed(()=>records.value.filter(r=>recordLabel(r).toLowerCase().includes(search.value.toLowerCase())))
const sellerFields=[{key:'recipient_name',label:'مسؤول تسليم الشحنات',required:true},{key:'seller_kind',label:'صفة البائع',type:'select',required:true,items:[{value:'individual',title:'فرد'},{value:'unregistered_business',title:'نشاط غير مسجل رسميًا'},{value:'registered_business',title:'منشأة مسجلة رسميًا'}]},{key:'tax_status',label:'حالة التسجيل في ضريبة البيع',type:'select',required:true,items:[{value:'not_registered',title:'غير مسجل'},{value:'registered',title:'مسجل'},{value:'exempt',title:'معفى بحسب حالتي'}]},{key:'registration_number',label:'رقم التسجيل',required:true,when:f=>f.tax_status==='registered'},{key:'tax_mode',label:'السعر والضريبة',type:'select',required:true,when:f=>f.tax_status==='registered',items:[{value:'included',title:'السعر يشمل الضريبة'},{value:'exclusive',title:'تضاف الضريبة للسعر'}]},{key:'rate_percent',label:'نسبة الضريبة %',type:'number',required:true,min:0,max:100,when:f=>f.tax_status==='registered'},{key:'basis',label:'إفادة توضح الحالة الفعلية لنشاطك',type:'textarea',required:true,help:'لا نفترض تسجيلًا أو إعفاءً نيابةً عنك. حفظ الإفادة لا يمثل اعتمادًا من الإدارة.'}]
const fields=computed(()=>schema.value?[...schema.value.fields,...(user.hasPermission('admin.super')&&['email','whatsapp','templates','automation'].includes(key.value)?[{key:'is_global',label:'إعداد عام لجميع الشركات — إدارة المنصة فقط',type:'checkbox'}]:[])]:({company_extra:[{key:'website',label:'موقع الشركة الإلكتروني',type:'url'}],seller_identity:sellerFields,locations:[{key:'branch_id',label:'الفرع الرئيسي',type:'select',source:'branches',required:true},{key:'branch_name',label:'اسم الفرع',required:true},{key:'warehouse_id',label:'المخزن الرئيسي',type:'select',source:'warehouses'},{key:'name',label:'اسم المخزن',required:true},{key:'location',label:'العنوان التفصيلي',required:true}],invoices:[{key:'is_active',label:'تفعيل نوع الفاتورة للشركة',type:'checkbox'}]})[key.value]||[])
const stepFields=computed(()=>[{key:'delay_days',label:'عدد الأيام بالنسبة للموعد',type:'number',default:0,min:String(form.value.event_type||'').startsWith('store.')?0:-365,max:365},{key:'channel_choice',label:'قناة الإرسال',type:'select',items:(String(form.value.event_type||'').startsWith('store.')?[{value:'email',title:'البريد'}]:[{value:'email',title:'البريد'},{value:'whatsapp',title:'واتساب'},{value:'both',title:'البريد وواتساب'}]),required:true},{key:'template_id',label:'قالب الرسالة',type:'select',source:'notification-templates',required:true},{key:'is_active',label:'خطوة نشطة',type:'checkbox'}])
function recordLabel(r){return String(r[schema.value?.label]||r.full_name||r.nickname||r.name||r.label||(key.value==='conversions'?`${r.from_unit?.name||r.from_unit_id} ← ${r.to_unit?.name||r.to_unit_id}`:r.id))}
function rememberBaseline(){baseline.value=JSON.stringify(form.value)}
const dirty=()=>JSON.stringify(form.value)!==baseline.value
async function load(){const ticket=++sequence,selected=key.value,company=user.currentUser?.active_company_id;if(!selected)return;pickingImage.value=false;loading.value=true;error.value='';message.value='';allowed.value=false;sources.value={};records.value=[];view.value='list';editingId.value=null;search.value='';form.value={};rememberBaseline();
 try{
  if(!store.snapshot||store.snapshot.company_id!==Number(company))await store.load(company)
  if(ticket!==sequence||selected!==key.value)return
  allowed.value=manager.value||user.hasPermission(optionPermissions[selected])||selected==='location'
  if(!allowed.value)throw Error('هذا الإعداد يحتاج صلاحية من مسؤول الشركة.')
  if(selected==='location'){form.value=clone(store.panelDraft||{});rememberBaseline();return}
  if(selected==='logo')return
  if(recordMode.value){const response=await api.get('/'+endpoint.value,{params:{per_page:50,page:1,company_id:company}});if(ticket!==sequence)return;records.value=listData(response);page.value=1;lastPage.value=response.data?.meta?.last_page||response.data?.data?.last_page||1}
  else if(selected==='subscription'){const r=await api.get('/saas/my-subscription');if(ticket===sequence)subscription.value=r.data?.data?.subscription||r.data?.data||null}
  else if(['billing','cash_customer'].includes(selected)){const d=snapshot.value.data,s=d.settings||{};form.value={invoice_type_ids:[...d.active_invoice_type_ids],create_invoice_types:false,payment_method_id:s.setup_payment_method_id||d.payment_methods[0]?.id||null,payment_method_name:'',create_cash_box:false,create_cash_customer:false,print_format:s.print_settings?.print_format||'standard',show_logo:s.print_settings?.show_logo??true,footer_text:s.print_settings?.footer_text||''}}
  else if(selected==='company_extra')form.value={website:snapshot.value.data.company.website||''}
  else if(selected==='seller_identity'){const p=snapshot.value.data.store?.profile||{},tax=p.tax_profile||{};form.value={recipient_name:p.pickup_address?.recipient_name||'',seller_kind:p.business_profile?.seller_kind||null,tax_status:tax.status==='unconfigured'?null:tax.status,tax_mode:tax.mode||'none',rate_percent:Number(tax.rate_bps||0)/100,registration_number:tax.registration_number||null,basis:tax.basis||''}}
  else if(selected==='locations'){const d=snapshot.value.data,b=d.branches.find(b=>b.is_default)||d.branches[0],w=d.warehouses.find(w=>w.is_default)||d.warehouses[0];sources.value={branches:d.branches,warehouses:d.warehouses};form.value={branch_id:b?.id||null,branch_name:b?.name||'الفرع الرئيسي',warehouse_id:w?.id||null,name:w?.name||'المخزن الرئيسي',location:w?.location||'',latitude:w?.latitude??null,longitude:w?.longitude??null,location_confirmed:!!w?.location_confirmed}}
  rememberBaseline()
 }catch(e){if(ticket===sequence)error.value=e.response?.data?.message||e.message||'تعذر تحميل الإعداد. أعد المحاولة.'}finally{if(ticket===sequence)loading.value=false}}
async function loadMore(){if(loading.value)return;loading.value=true;const ticket=sequence;try{const r=await api.get('/'+endpoint.value,{params:{per_page:50,page:page.value+1,company_id:user.currentUser?.active_company_id}});if(ticket===sequence){records.value.push(...listData(r));page.value++}}catch{error.value='تعذر تحميل بقية السجلات.'}finally{if(ticket===sequence)loading.value=false}}
async function loadSources(){const names=[...new Set(fields.value.filter(f=>f.source).map(f=>f.source))];if(key.value==='roles')names.push('permissions');if(schema.value?.steps)names.push('notification-templates');const ticket=sequence;await Promise.all(names.map(async name=>{const r=await api.get('/'+name,{params:{per_page:200,company_id:user.currentUser?.active_company_id}});if(ticket===sequence)sources.value[name]=name==='permissions'?(r.data?.data||[]):listData(r)}))}
async function edit(record){error.value='';message.value='';editingId.value=record?.id||null;view.value='edit';form.value={};for(const f of fields.value)form.value[f.key]=record?.[f.key]??f.default??(f.type==='checkbox'?false:null);if(record)form.value={...form.value,...clone(record)};if(['users','roles'].includes(key.value)&&!record)form.value={};if(key.value==='users'&&!record)form.value={relation_types:['employee'],status:'active',is_active:true,branch_ids:[],company_ids:[user.currentUser?.active_company_id]};for(const f of fields.value)if(f.type==='password')form.value[f.key]='';if(schema.value?.steps)form.value.steps=(record?.steps||[]).map(s=>({...s,channel_choice:Array.isArray(s.channel)?(s.channel.length>1?'both':s.channel[0]):s.channel}));try{await loadSources();if(key.value==='permissions'){const r=await api.get('/users/'+record.id,{params:{permissions:1,sync_company_id:user.currentUser?.active_company_id}});permissionUser.value=r.data?.data||r.data}}catch(e){error.value=e.response?.data?.message||'تعذر تحميل بيانات النموذج.'}rememberBaseline()}
function back(){if(dirty()&&!window.confirm('هل تريد ترك التعديلات غير المحفوظة؟'))return;view.value='list';form.value={};rememberBaseline();message.value=''}
function cancel(){if(!dirty()||window.confirm('هل تريد إلغاء التعديلات الحالية؟')){form.value=JSON.parse(baseline.value||'{}');error.value=''}}
function close(){if(saving.value)return;if(dirty()&&!window.confirm('توجد تعديلات لم تحفظ. هل تريد إغلاق النافذة؟'))return;sequence++;store.closePanel()}
async function savePayload(payload){saving.value=true;error.value='';message.value='';const ticket=sequence,selected=key.value,company=user.currentUser?.active_company_id;try{
 const r=editingId.value?await api.put('/'+endpoint.value+'/'+editingId.value,payload):await api.post('/'+endpoint.value,payload)
 if(ticket!==sequence||selected!==key.value)return
 if(r.data?.success===false||r.data?.status===false)throw Error(r.data.message||'تعذر الحفظ.')
 await store.load(company);await load();message.value='تم حفظ التغييرات.'
 }catch(e){if(ticket===sequence)error.value=Object.values(e.response?.data?.errors||{}).flat().join('، ')||e.response?.data?.message||e.message||'تعذر الحفظ؛ تعديلاتك ما زالت موجودة.'}finally{saving.value=false}}
async function saveUser(data){await savePayload(data)}
async function save(){if(saving.value||!canEditCurrent.value)return;if(recordMode.value){const payload={};for(const f of fields.value){if(f.when&&!f.when(form.value))continue;if(f.type==='password'&&!form.value[f.key])continue;payload[f.key]=form.value[f.key]??null}if(['brands','categories','payments'].includes(key.value)&&form.value.image_id)payload.image_id=form.value.image_id;if(schema.value?.map)Object.assign(payload,{latitude:form.value.latitude??null,longitude:form.value.longitude??null,location_confirmed:!!form.value.location_confirmed});if(schema.value?.steps)payload.steps=(form.value.steps||[]).map((s,i)=>({id:s.id,step_number:i+1,delay_days:Number(s.delay_days)||0,channel:s.channel_choice==='both'?['email','whatsapp']:[s.channel_choice||'email'],template_id:s.template_id,is_active:!!s.is_active}));await savePayload(payload);return}
 saving.value=true;error.value='';const ticket=sequence;try{let section=key.value,payload=clone(form.value);if(section==='seller_identity'){payload.rate_bps=payload.tax_status==='registered'?Math.round(Number(payload.rate_percent||0)*100):0;if(payload.tax_status!=='registered'){payload.tax_mode='none';payload.registration_number=null}delete payload.rate_percent}if(section==='cash_customer'){section='cash_customer';payload={create:!!form.value.create_cash_customer}}
 const r=await api.put('/guidance/setup/options/'+section,{revision:snapshot.value.revision,data:payload});if(ticket!==sequence)return;store.snapshot=r.data.data;rememberBaseline();message.value='تم حفظ التغييرات. يمكنك العودة للدليل ومتابعة مسودتك.'
 }catch(e){if(ticket===sequence)error.value=Object.values(e.response?.data?.errors||{}).flat().join('، ')||e.response?.data?.message||'تعذر الحفظ؛ تعديلاتك ما زالت موجودة.'}finally{saving.value=false}}
async function saveLocation(){if(!form.value.location_confirmed)return;if(form.value.saveWarehouse){saving.value=true;try{await api.put('/warehouses/'+form.value.id,{latitude:form.value.latitude,longitude:form.value.longitude,location_confirmed:true});await store.load(user.currentUser?.active_company_id);store.closePanel()}catch(e){error.value=e.response?.data?.message||'تعذر حفظ نقطة المخزن.'}finally{saving.value=false}}else{store.locationAccept?.(clone(form.value));store.closePanel()}}
function selectLogo(asset){if(pickingImage.value){if(key.value==='users'){form.value.images_ids=[asset.id];form.value.avatar_url=asset.url}else form.value.image_id=asset.id;pickingImage.value=false;return}store.locationAccept?.(asset);store.closePanel()}
async function testConnection(){if(!window.confirm('سيُرسل النظام رسالة فعلية إلى المستلم الذي أدخلته. هل تريد المتابعة؟'))return;saving.value=true;error.value='';message.value='';try{const r=await api.post('/'+schema.value.endpoint+'/'+editingId.value+'/test',{recipient:testRecipient.value});if(r.data?.success===false||r.data?.status===false)throw Error(r.data.message);message.value=r.data?.message||'اكتمل اختبار الإرسال.';await store.load(user.currentUser?.active_company_id)}catch(e){error.value=e.response?.data?.message||e.message||'فشل اختبار الاتصال.'}finally{saving.value=false}}
async function permissionSaved(){await store.load(user.currentUser?.active_company_id);await load();message.value='تم حفظ الصلاحيات.'}
watch(()=>store.panel,()=>load(),{immediate:true})
watch(()=>form.value.branch_id,id=>{if(key.value!=='locations')return;const b=sources.value.branches?.find(b=>b.id===id);if(b)form.value.branch_name=b.name})
watch(()=>form.value.warehouse_id,id=>{if(key.value!=='locations')return;const w=sources.value.warehouses?.find(w=>w.id===id);if(w)Object.assign(form.value,{name:w.name,location:w.location,latitude:w.latitude,longitude:w.longitude,location_confirmed:!!w.location_confirmed})})
</script>
